package com.example.urlshortener.model; import jakarta.persistence.Column; import jakarta.persistence.Entity; import jakarta.persistence.GeneratedValue; import jakarta.persistence.GenerationType; import jakarta.persistence.Id; import jakarta.persistence.Table; import java.time.LocalDateTime; @Entity @Table(name = "shortened_urls") public class ShortenedUrl { @Id @GeneratedValue(strategy = GenerationType.IDENTITY) private Long id; @Column(name = "original_url", nullable = false, length = 2048) private String originalUrl; @Column(name = "short_code", nullable = false, unique = true, length = 10) private String shortCode; @Column(name = "created_at", nullable = false, updatable = false) private LocalDateTime createdAt; public ShortenedUrl() { this.createdAt = LocalDateTime.now(); } public ShortenedUrl(String originalUrl, String shortCode) { this.originalUrl = originalUrl; this.shortCode = shortCode; this.createdAt = LocalDateTime.now(); } public Long getId() { return id; } public String getOriginalUrl() { return originalUrl; } public void setOriginalUrl(String originalUrl) { this.originalUrl = originalUrl; } public String getShortCode() { return shortCode; } public void setShortCode(String shortCode) { this.shortCode = shortCode; } public LocalDateTime getCreatedAt() { return createdAt; } @Override public String toString() { return "ShortenedUrl{" + "id=" + id + ", originalUrl='" + originalUrl + '\'' + ", shortCode='" + shortCode + '\'' + ", createdAt=" + createdAt + '}'; } }